import React from "react";
import Navbar from "../components/navbar"; // Top navigation bar
import SidePanel from "../components/sidePanel"; // Side panel with logo and description
import "./home.css"; // Import styles

const Home = () => {
  return (
    <div className="home-container">
      <Navbar />
      <div className="home-content">
        <SidePanel />
        <div className="main-content">
          <h1>Welcome to the FYP Automation System</h1>
          <p>This system helps manage final year projects efficiently with features like proposal submission, group management, and progress tracking.</p>
        </div>
      </div>
    </div>
  );
};

export default Home;
